<?php require_once '../config/helpers.php';require_customer();$st=$pdo->prepare("SELECT b.*,s.name service_name FROM bookings b JOIN services s ON s.id=b.service_id WHERE b.customer_id=? ORDER BY b.event_date DESC,b.event_time DESC");$st->execute([$_SESSION['customer_id']]);$bookings=$st->fetchAll();$page_title='My Bookings';$asset_prefix='../';$home_link='../index.php';$services_link='../index.php#services';$login_link='../login.php';$register_link='../register.php';$logout_link='../logout.php';$customer_link='dashboard.php';include '../includes/header.php'; ?><h1 class="section-title">Hello, <?= e($_SESSION['customer_name']) ?></h1><div class="actions"><a class="btn" href="book.php">+ Book an Appointment</a></div><h2>My Booking History</h2><div class="panel table-wrap"><table class="table"><thead><tr><th>Service</th><th>Event date</th><th>Time</th><th>Location</th><th>Address</th><th>Status</th></tr></thead><tbody><?php foreach($bookings as $b): ?><tr><td><?= e($b['service_name']) ?></td><td><?= e($b['event_date']) ?></td><td><?= e(date('h:i A',strtotime($b['event_time']))) ?></td><td><?= e($b['event_location']) ?></td><td><?= e($b['full_address']) ?></td><td><span class="badge <?= e($b['status']) ?>"><?= e($b['status']) ?></span></td></tr><?php endforeach; ?><?php if(!$bookings): ?><tr><td colspan="6">No bookings yet. <a href="book.php">Book your first appointment</a>.</td></tr><?php endif; ?></tbody></table></div><?php include '../includes/footer.php'; ?>
